<?php
require_once __DIR__.'/includes/bootstrap.php';if(!logged())go('login.php');
$pages=[
'dashboard'=>['Overview','Your academic workspace',''],
'courses'=>['Courses','Manage the course catalog','tbl_course'],
'instructors'=>['Instructors','Manage faculty records','tbl_instructors'],
'school-years'=>['School Years','Manage academic year records','tbl_schoolyear'],
'terms'=>['Terms','Manage academic terms','tbl_term'],
'sections'=>['Sections','Manage class sections','tbl_section'],
'year-levels'=>['Year Levels','Manage year levels','tbl_yearlevel'],
'students'=>['Students','Manage student records','tbl_students'],
'accounts'=>['Accounts','Manage system accounts','tbl_account']];
$access=['dashboard'=>['admin','registrar','dean','instructor','student'],'courses'=>['admin','registrar','dean','instructor','student'],'instructors'=>['admin','registrar','dean'],'school-years'=>['admin','registrar','dean'],'terms'=>['admin','registrar'],'sections'=>['admin','dean','instructor'],'year-levels'=>['admin','dean'],'students'=>['admin','registrar','dean'],'accounts'=>['admin']];
$page=$_GET['page']??'dashboard';$r=role();if(!isset($pages[$page])||!in_array($r,$access[$page],true))$page='denied';
[$title,$subtitle,$table]=$pages[$page]??['Access restricted','Your account cannot access this page.',''];
$cols=$table?cols($table):[];$pk='ID';foreach($cols as $c)if($c['Key']==='PRI'){$pk=$c['Field'];break;}
$msg='';$err='';
if($table&&$_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['action'])){checkCsrf();try{
if($_POST['action']==='delete'){$id=$_POST['id'];$s=$conn->prepare("DELETE FROM `$table` WHERE `$pk`=?");$s->bind_param('s',$id);$s->execute();$msg='Record deleted.';}
if($_POST['action']==='save'){$id=$_POST['id']??'';$vals=[];foreach($cols as $c){$f=$c['Field'];if($f===$pk||strtoupper($f)==='PASSWORD'||stripos($c['Extra'],'auto_increment')!==false)continue;$vals[$f]=trim($_POST[$f]??'');}
if($table==='tbl_account'&&!empty($_POST['NEW_PASSWORD']))$vals['PASSWORD']=password_hash($_POST['NEW_PASSWORD'],PASSWORD_DEFAULT);
if($id){$set=[];$args=[];$types='';foreach($vals as $f=>$v){$set[]="`$f`=?";$args[]=$v;$types.='s';}if($set){$args[]=$id;$types.='s';$s=$conn->prepare("UPDATE `$table` SET ".implode(',',$set)." WHERE `$pk`=?");$s->bind_param($types,...$args);$s->execute();}$msg='Record updated.';}
else{if($table==='tbl_account'&&empty($vals['PASSWORD'])){$err='A password is required for new accounts.';}else{$f=array_keys($vals);$q=array_fill(0,count($f),'?');$args=array_values($vals);$types=str_repeat('s',count($args));$s=$conn->prepare("INSERT INTO `$table` (`".implode('`,`',$f)."`) VALUES (".implode(',',$q).")");if($args)$s->bind_param($types,...$args);$s->execute();$msg='Record created.';}}}
}catch(Throwable $e){error_log($e->getMessage());$err='Could not save. Check required fields and unique values.';}}
$edit=null;if($table&&isset($_GET['edit'])){$id=$_GET['edit'];$s=$conn->prepare("SELECT * FROM `$table` WHERE `$pk`=?");$s->bind_param('s',$id);$s->execute();$edit=$s->get_result()->fetch_assoc();}
$q=trim($_GET['q']??'');$rows=[];if($table){$sql="SELECT * FROM `$table`";$args=[];$types='';if($q){$parts=[];foreach($cols as $c){if(strtoupper($c['Field'])==='PASSWORD')continue;$parts[]="CAST(`{$c['Field']}` AS CHAR) LIKE ?";$args[]='%'.$q.'%';$types.='s';}if($parts)$sql.=' WHERE '.implode(' OR ',$parts);}$sql.=" ORDER BY `$pk` DESC LIMIT 100";$s=$conn->prepare($sql);if($args)$s->bind_param($types,...$args);$s->execute();$rows=$s->get_result()->fetch_all(MYSQLI_ASSOC);}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> · CampusFlow</title><link rel="stylesheet" href="assets/style.css"><script src="https://unpkg.com/lucide@latest"></script></head><body><aside class="sidebar"><a class="logo" href="index.php"><b>C</b> Campus<span>Flow</span></a><div class="campus">▦ &nbsp; Campus portal <small><?=e(ucfirst($r))?></small></div><nav><?php foreach($pages as $k=>$v):if(!in_array($r,$access[$k]??[],true))continue;?><a class="<?=$page===$k?'active':''?>" href="index.php?page=<?=$k?>"><i data-lucide="<?=['dashboard'=>'layout-dashboard','courses'=>'book-open','instructors'=>'users','school-years'=>'calendar-days','terms'=>'calendar-range','sections'=>'layers','year-levels'=>'graduation-cap','students'=>'contact','accounts'=>'shield'][$k]?>"></i><?=e($v[0])?></a><?php endforeach;?></nav><a class="logout" href="logout.php">↗ &nbsp; Sign out</a></aside><main><header><div class="crumb">CampusFlow <span>/</span> <?=e($title)?></div><div class="user"><b><?=e(strtoupper(substr($_SESSION['USERNAME'],0,1)))?></b><?=e($_SESSION['USERNAME'])?> <small><?=e(ucfirst($r))?></small></div></header><section class="heading"><small class="kicker">YOUR CAMPUS, IN ONE PLACE</small><h1><?=e($title)?></h1><p><?=e($subtitle)?></p></section>
<?php if($page==='dashboard'):?><div class="hero"><small>ACADEMIC WORKSPACE</small><h2>Good day, <?=e($_SESSION['USERNAME'])?> ✦</h2><p>Keep your campus operations moving, all from one place.</p></div><h2 class="section-title">At a glance</h2><div class="stats"><?php foreach([['Courses','tbl_course'],['Instructors','tbl_instructors'],['Students','tbl_students'],['School years','tbl_schoolyear']] as [$n,$t]):?><article><small><?=e($n)?></small><strong><?=number_format(countRows($t))?></strong><span>Records in <?=$t?></span></article><?php endforeach;?></div><div class="panel"><h3>Quick access</h3><div class="quick"><?php foreach(['courses','instructors','sections','students'] as $k):if(in_array($r,$access[$k],true)):?><a href="index.php?page=<?=$k?>"><?=e($pages[$k][0])?> <b>↗</b></a><?php endif;endforeach;?></div></div>
<?php elseif($page==='denied'):?><div class="panel">Access restricted. Contact your administrator if you need access.</div>
<?php else:?>
<?php if($msg):?><div class="notice"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?>
<div class="toolbar"><form><input type="hidden" name="page" value="<?=e($page)?>"><input name="q" value="<?=e($q)?>" placeholder="Search records..."><button class="secondary">Search</button></form><a class="primary" href="index.php?page=<?=$page?>&new=1">＋ Add record</a></div>
<?php if(isset($_GET['new'])||$edit):?><div class="panel"><div class="panel-head"><h3><?=$edit?'Edit record':'Add new record'?></h3><a href="index.php?page=<?=$page?>">✕</a></div><form method="post" class="formgrid"><?=csrfInput()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e($edit[$pk]??'')?>"><?php foreach($cols as $c):$f=$c['Field'];if($f===$pk||strtoupper($f)==='PASSWORD'||stripos($c['Extra'],'auto_increment')!==false)continue;?><label><?=e(ucwords(str_replace('_',' ',$f)))?><input name="<?=e($f)?>" value="<?=e($edit[$f]??'')?>" <?=($c['Null']==='NO'&&$c['Default']===null)?'required':''?>></label><?php endforeach;?><?php if($table==='tbl_account'):?><label><?=$edit?'New password (optional)':'Password *'?><input type="password" name="NEW_PASSWORD" <?=$edit?'':'required'?>></label><?php endif;?></div><div class="formfoot"><a class="secondary" href="index.php?page=<?=$page?>">Cancel</a><button class="primary">Save record</button></div></form></div><?php endif;?>
<div class="panel tablepanel"><div class="panel-head"><div><h3><?=e($title)?> directory</h3><small><?=count($rows)?> records shown · up to 100</small></div><small><?=countRows($table)?> TOTAL</small></div><div class="scroll"><table><thead><tr><?php foreach($cols as $c):if(strtoupper($c['Field'])==='PASSWORD')continue;?><th><?=e(ucwords(str_replace('_',' ',$c['Field'])))?></th><?php endforeach;?><th>Actions</th></tr></thead><tbody><?php foreach($rows as $row):?><tr><?php foreach($cols as $c):$f=$c['Field'];if(strtoupper($f)==='PASSWORD')continue;?><td><?=e($row[$f]??'—')?></td><?php endforeach;?><td class="actions"><a href="index.php?page=<?=$page?>&edit=<?=e($row[$pk])?>">Edit</a><form method="post" onsubmit="return confirm('Delete this record?')"><?=csrfInput()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($row[$pk])?>"><button>Delete</button></form></td></tr><?php endforeach;?></tbody></table><?php if(!$rows):?><div class="empty">No records found. Add a record or adjust your search.</div><?php endif;?></div></div><?php endif;?></main><script>lucide.createIcons()</script></body></html>
